SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END hire_cohort, COUNT(DISTINCT salary) unique_managers FROM employees WHERE UPPER(email) LIKE '%ARO%' AND UPPER(TRIM(email)) = 'GRACE.KIM@GMAIL.COM' AND full_name IS NOT NULL GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END;
